function renderDock(){const total=Object.values(draft.cards).reduce((a,b)=>a+b,0);$('#dock-name').textContent=draft.name;$('#dock-total').textContent=total;$('#saved-count').textContent=saved.length;$('#dock-cards').innerHTML=Object.entries(draft.cards).slice(-5).map(([id,n])=>`<div class="dock-row"><b>${n}×</b><span>${esc(catalog.has(id)?displayName(catalog.get(id)):id)}</span></div>`).join('');}
function checkJP(v){if(!jpRestrictions)return v;const names=new Map(),codeNames=new Map(cards.filter(c=>c.language==='JP').map(c=>[c.code,c.name]));for(const [id,n] of Object.entries(draft.cards)){const c=catalog.get(id);if(c)names.set(c.name,(names.get(c.name)||0)+n);}if(draft.format!=='Neo Standard'){const bannedNames=new Set(jpRestrictions.standardBans.map(code=>codeNames.get(code)).filter(Boolean));for(const name of names.keys())if(bannedNames.has(name))v.errors.push(name+': banned by Japanese Standard/Side list');return v;}for(const r of jpRestrictions.rules){const used=r.options.map(option=>[...new Set(option.map(code=>codeNames.get(code)).filter(Boolean))]).map(ns=>ns.reduce((n,name)=>n+(names.get(name)||0),0));const bad=r.kind==='choice'?used.filter(n=>n>0).length>1:used.some(n=>n>r.limit);if(bad){const msg=`${r.title}: Japanese ${r.kind==='choice'?'choice restriction':r.limit+'-copy limit'}`;if(r.conditional)v.warnings.push(msg+' — special deck exception requires review.');else v.errors.push(msg);}}return v;}
function restrictionCheck(v){if(draft.language==='JP')return checkJP(v);if(!restrictions)return v;const counts=new Map();for(const [id,n] of Object.entries(draft.cards)){const c=catalog.get(id);if(!c)continue;const base=c.code.replace(/(SSP|SP|OFR|ABR|IGP|SR|RRR|SEC|S)$/,'');counts.set(base,(counts.get(base)||0)+n);}for(const r of restrictions.limits){let n=r.codes.reduce((n,c)=>n+(counts.get(c)||0),0);if(n>r.limit)v.errors.push(`${r.name}: ${n}/${r.limit} allowed by EN restriction list`);}for(const group of restrictions.choices){const used=group.options.filter(codes=>codes.some(c=>counts.get(c)));if(used.length>group.choose)v.errors.push(`${group.title}: choose ${group.choose}; ${used.length} restricted choices present`);}if(draft.format==='Neo Standard'){const series=[...new Set(Object.keys(draft.cards).map(id=>catalog.get(id)?.series).filter(Boolean))];if(series.length>1&&!restrictions.groups.some(g=>series.every(s=>g.codes.includes(s))))v.errors.push('Title codes do not share an imported official Neo Standard group. Check special title exceptions.');}return v;}
function renderDeck(){renderDock();$('#deck-name').value=draft.name;$('#format').value=draft.format;$('#deck-language').value=draft.language;const v=restrictionCheck(validate(draft.cards,catalog,draft.format,draft.language));$('#validation').innerHTML=`<div class="validation"><b>${v.total}/50 cards · ${v.cx}/8 climax</b><div class="${v.errors.length?'bad':'good'}">${v.errors.length?v.errors.map(esc).join('<br>'):'Basic construction checks passed'}</div>${v.warnings.map(w=>`<small>${esc(w)}</small>`).join('')}</div>`;renderDeckOrigin();$('#deck-cards').innerHTML=Object.entries(draft.cards).map(([id,n])=>{const c=catalog.get(id);return `<div class="deck-row" data-hover-card="${esc(id)}">${c?`<button class="art-button" style="width:56px" data-inspect="${esc(id)}">${img(c)}</button>`:''}<div><p>${esc(c?displayName(c):id)}</p><small>${esc(c?.code||id)}</small><small class="card-series">${esc(c?fullSeries(c):'Series name unavailable')}</small><button class="deck-zoom" data-inspect="${esc(id)}" aria-label="Inspect ${esc(c?displayName(c):id)}">⤢ Inspect</button><div><button data-decrement="${esc(id)}" aria-label="Remove one">−</button> <b>${n}</b> <button data-add="${esc(id)}" aria-label="Add one">+</button> <button data-remove="${esc(id)}">Remove</button></div></div></div>`;}).join('')||'<p class="muted">Your deck is a blank canvas. Add cards from the library.</p>';$('#saved-list').innerHTML=saved.map((d,i)=>`<div class="saved-item"><b>${esc(d.name)}</b><p class="muted">${Object.values(d.cards).reduce((a,b)=>a+b,0)} cards · ${esc(d.language)} · ${esc(d.format)}</p><button data-load="${i}">Load</button><button data-duplicate="${i}">Duplicate</button>${d.included?'<small class="included-badge">Included deck</small>':'<button data-delete="'+i+'">Delete</button>'}</div>`).join('')||'<p class="muted">No saved decks yet.</p>';}
$('#deck-name').oninput=e=>{draft.name=e.target.value;saveDraft();renderDock();};['format','deck-language'].forEach(id=>$('#'+id).onchange=()=>{draft.format=$('#format').value;draft.language=$('#deck-language').value;saveDraft();renderDeck();});$('#save-deck').onclick=()=>{if(!draft.name.trim())return toast('Give your deck a name.');draft.id=draft.id||crypto.randomUUID();const i=saved.findIndex(d=>d.id===draft.id);if(i<0)saved.push(structuredClone(draft));else saved[i]=structuredClone(draft);persist('ws-decks',saved);saveDraft();renderDeck();toast('Deck saved on this browser.');};$('#new-deck').onclick=()=>{draft={name:'Untitled deck',cards:{},format:'Standard',language:'EN'};saveDraft();renderDeck();};
$('#example-deck').onclick=async()=>{try{const r=await fetch('data/example-deck.json');if(!r.ok)throw Error('Study deck unavailable.');draft=await r.json();delete draft.id;saveDraft();renderDeck();toast('50-card study deck loaded. Save it to use at the practice table.');}catch(e){toast(e.message);}};
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export-deck').onclick=()=>download(draft.name+'.json',JSON.stringify({...draft,schema:'ws-atelier-deck-v1'},null,2));$('#export-text').onclick=()=>download(draft.name+'.txt',Object.entries(draft.cards).map(([id,n])=>`${n} ${id.includes(':art:')?id:catalog.get(id)?.code||id}`).join('\n'),'text/plain');$('#import-deck').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const t=await f.text();let d;if(t.trim().startsWith('{')){d=JSON.parse(t);if(!d.cards||typeof d.cards!=='object')throw Error('Expected a cards object.');for(const [id,n] of Object.entries(d.cards))if(!catalog.has(id)||!Number.isInteger(n)||n<1||n>500)throw Error('Unknown card or invalid count: '+id);d={name:String(d.name||f.name),cards:d.cards,format:['Standard','Side','Neo Standard'].includes(d.format)?d.format:'Standard',language:d.language==='JP'?'JP':'EN'};}else{d={name:f.name.replace(/\.txt$/,''),cards:{},format:'Standard',language:$('#deck-language').value};for(const line of t.split(/\r?\n/).filter(x=>x.trim())){const m=line.trim().match(/^(\d+)\s*[x×]?\s+(.+)$/);if(!m)throw Error('Expected “4 CARD/NUMBER” on each line.');const matches=cards.filter(c=>c.language===d.language&&c.code===m[2].trim());const c=catalog.get(m[2].trim())||(matches.length===1?matches[0]:null);if(matches.length>1&&!catalog.has(m[2].trim()))throw Error('Multiple artwork variants share '+m[2]+'. Use a JSON deck export to preserve the exact artwork.');if(!c)throw Error('Card not found: '+m[2]);const n=+m[1];if(n<1||n>500)throw Error('Invalid count');d.cards[c.id]=(d.cards[c.id]||0)+n;}}draft=d;saveDraft();renderDeck();toast('Deck imported. Review construction checks before saving.');}catch(e){toast(e.message);}e.target.value='';};$('#practice-deck').onclick=()=>{if(!saved.some(d=>d.id===draft.id))$('#save-deck').click();view('practice');};

function renderDeckOrigin(){const d=draft.provenance,original=includedDecks.find(x=>x.provenance?.product===d?.product),unaltered=original&&Object.keys(original.cards).length===Object.keys(draft.cards).length&&Object.entries(original.cards).every(([id,n])=>draft.cards[id]===n);$('#deck-origin').innerHTML=d?'<div class="notice"><b>'+esc(draft.name)+'</b><p>'+esc(unaltered?d.note:'Edited deck based on the original preconstructed configuration. Its current list and construction checks are shown below.')+'</p><a href="'+esc(d.product)+'" target="_blank" rel="noopener">Official product ↗</a> · <a href="'+esc(d.quantities)+'" target="_blank" rel="noopener">Published full quantity list ↗</a><p>Full card list below · '+Object.values(draft.cards).reduce((a,b)=>a+b,0)+' cards</p></div>':'';}
function duplicateDeck(d){draft=structuredClone(d);draft.id=crypto.randomUUID();draft.name+=' (copy)';delete draft.included;saved.push(structuredClone(draft));persist('ws-decks',saved);saveDraft();renderDeck();toast('Editable copy saved.');}
