function installIncludedDecks(decks){for(const deck of decks)if(!saved.some(d=>d.id===deck.id))saved.push(structuredClone(deck));persist('ws-decks',saved);}

function renderSetup(){for(const id of ['p1-deck','p2-deck']){const old=$('#'+id).value;$('#'+id).innerHTML=saved.map((d,i)=>`<option value="${i}">${esc(d.name)}</option>`).join('');if(old)$('#'+id).value=old;}}
$('#new-match').onclick=()=>{$('#match-setup').hidden=false;renderSetup();};$('#start-match').onclick=()=>{if(!saved.length)return toast('Save a deck in the deck editor first.');const decks=[$('#p1-deck').value,$('#p2-deck').value].map(i=>saved[+i]?.cards);if(decks.some(d=>!d||!Object.keys(d).length))return toast('Choose two non-empty decks.');match=createMatch(decks);match.deckNames=[$('#p1-deck').value,$('#p2-deck').value].map(i=>saved[+i].name);match.active=$('#first-player').value==='random'?Math.floor(Math.random()*2):+$('#first-player').value;match.players.forEach((_,p)=>draw(match,p,5));match.log=['Opening hands drawn. Player '+(match.active+1)+' goes first.'];history=[];future=[];selected=[];persist('ws-match',match);$('#match-setup').hidden=true;$('#control-player').value=String(match.active);renderMatch();};
const cp=()=>+$('#control-player').value,amount=()=>Math.max(1,Math.min(50,Math.floor(+$('#amount').value)||1));
function commit(label,fn){if(!match)return toast('Start a match first.');const before=structuredClone(match);try{fn();if(resolver.auto(match).enabled)resolver.afterMutation(match,before);if(before.auto?.choice&&!match.auto?.choice&&!match.auto?.attack)$('#control-player').value=String(match.active);history.push(before);if(history.length>100)history.shift();future=[];match.log.unshift(`T${match.turn} · ${label}`);match.log=match.log.slice(0,150);persist('ws-match',match);selected=selected.filter(r=>match.players[r.p].zones[r.z]?.some(c=>c.uid===r.uid));renderMatch();if(pile)renderPile();}catch(e){match=before;toast(e.message);}}
