function ref(p,z,c){return {p,z,uid:c.uid};}const isSelected=(p,z,c)=>selected.some(r=>r.p===p&&r.z===z&&r.uid===c.uid);
function toggle(p,z,uid){const i=selected.findIndex(r=>r.p===p&&r.z===z&&r.uid===uid);if(i<0)selected.push({p,z,uid});else selected.splice(i,1);renderMatch();if(pile)renderPile();}
function visible(p,z,c){return c.revealed||(!c.faceDown&&(z!=='deck'&&z!=='stock'&&(z!=='hand'||p===cp()||$('#show-hidden').checked)));}
function tiny(p,z,c){const info=catalog.get(c.id);return visible(p,z,c)&&info?img(info,c.orientation):'<span class="card-back" aria-label="Hidden card">W</span>';}
function zoneHTML(p,z){const a=match.players[p].zones[z],top=a.at(-1);return '<div class="zone" role="button" tabindex="0" data-pile="'+p+'|'+z+'" '+(top?'data-ref="'+p+'|'+z+'|'+top.uid+'"':'')+' aria-label="Inspect '+zoneName(z)+', '+a.length+' cards"><span class="zone-label">'+esc(zoneName(z).toUpperCase())+'</span>'+(top?tiny(p,z,top):'')+'<span class="zone-count"> '+a.length+'</span>'+(top&&visible(p,z,top)?'<button class="zone-zoom" data-inspect="'+esc(top.id)+'" aria-label="Inspect '+esc(displayName(catalog.get(top.id)))+'">⤢</button>':'')+'</div>';}
function stageHTML(p,z){const a=match.players[p].zones[z],c=a.at(-1),markers=match.players[p].zones['markers:'+z];return '<div class="zone stage-zone '+(c&&isSelected(p,z,c)?'selected':'')+'" data-stage="'+p+'|'+z+'" '+(c?'data-ref="'+p+'|'+z+'|'+c.uid+'"':'')+' role="button" tabindex="0" aria-label="'+zoneName(z)+(c&&visible(p,z,c)?' · '+esc(displayName(catalog.get(c.id))):'')+'"><span class="zone-label">'+esc(zoneName(z))+'</span>'+(c?tiny(p,z,c):'<span class="zone-count">◇</span>')+(c&&visible(p,z,c)?'<button class="zone-zoom" data-inspect="'+esc(c.id)+'" aria-label="Inspect '+esc(displayName(catalog.get(c.id)))+'">⤢</button>':'')+(c&&catalog.has(c.id)?'<button class="auto-soul" data-soul="'+p+'|'+z+'|'+c.uid+'" aria-label="Inspect current soul">Soul '+resolver.stats(match,{p,z,uid:c.uid}).soul+'</button>':'')+(c?.note?'<small>'+esc(c.note)+'</small>':'')+'<button class="marker-link" data-pile="'+p+'|markers:'+z+'">Markers '+markers.length+'</button>'+(a.length>1?'<button class="marker-link" style="bottom:10px" data-pile="'+p+'|'+z+'">'+a.length+' cards · inspect</button>':'')+'</div>';}
function playerHTML(p){const z=match.players[p].zones,hand=`<div class="hand"><span class="zone-label">HAND · ${z.hand.length}</span>${z.hand.map(c=>`<div class="hand-card-wrap" data-ref="${p}|hand|${c.uid}"><button class="hand-card ${isSelected(p,'hand',c)?'selected':''}" data-select="${p}|hand|${c.uid}" aria-label="${visible(p,'hand',c)?esc(displayName(catalog.get(c.id))):'Hidden hand card'}">${tiny(p,'hand',c)}</button>${visible(p,'hand',c)?`<button class="hand-zoom" data-inspect="${esc(c.id)}" aria-label="Inspect ${esc(displayName(catalog.get(c.id)))}">⤢</button>`:''}</div>`).join('')}<button data-pile="${p}|hand">Inspect hand</button></div>`;const front=`<div class="stage-row stage-front">${(p===1?['center-right','center-middle','center-left']:['center-left','center-middle','center-right']).map(a=>stageHTML(p,a)).join('')}</div>`,back=`<div class="stage-row stage-back">${(p===1?['back-right','back-left']:['back-left','back-right']).map(a=>stageHTML(p,a)).join('')}</div>`;return `<section class="player-mat ${p===1?'opponent':''}"><h3><span>PLAYER ${p+1} ${match.active===p?'· ACTIVE TURN':''}</span><span>Level ${z.level.length} · Clock ${z.clock.length}${z.level.length>=4?' · LOSS CONDITION':''}</span></h3><p class="player-deck-name">${esc(match.deckNames?.[p]||'Practice deck')}</p>${p===1?hand+back+front:front+back}<div class="zone-row">${['deck','waiting','stock','clock','level','memory'].map(a=>zoneHTML(p,a)).join('')}</div><div class="zone-row" style="grid-template-columns:1fr 1fr;margin-top:8px">${['climax','resolution'].map(a=>zoneHTML(p,a)).join('')}</div>${p===0?hand:''}${match.damage[p]?`<p class="notice">Damage pending: ${match.damage[p].remaining} remaining ${match.damage[p].canceled?'· CANCELED':''}</p>`:''}${!z.deck.length?'<p class="notice">Deck empty: refresh now when appropriate. Costs defer refresh and level-up until payment ends.</p>':''}${z.clock.length>=7?'<p class="notice">Level-up pending: inspect clock and select one of the bottom seven cards.</p>':''}</section>`;}
function renderMatch(){if(Number.isInteger(match?.auto?.choice?.p))$('#control-player').value=String(match.auto.choice.p);if(!match){$('#match-content').hidden=true;return;}$('#match-content').hidden=false;$('#table').innerHTML=playerHTML(1)+playerHTML(0);$('#turn-info').innerHTML=`<b>Turn ${match.turn} · Player ${match.active+1}</b><br>${phases[match.phase]} phase<br><small>${esc(match.step)}</small>`;$('#phase-override').innerHTML=phases.map((p,i)=>`<option value="${i}" ${i===match.phase?'selected':''}>${p}</option>`).join('');$('#attack-step').value=match.step;$('#selection-info').innerHTML=selected.length?selected.map(r=>{const c=match.players[r.p].zones[r.z].find(c=>c.uid===r.uid);return `<p><small>P${r.p+1} · ${esc(zoneName(r.z))}</small><br>${visible(r.p,r.z,c)?`<button class="link" data-inspect="${esc(c.id)}">${esc(displayName(catalog.get(c.id)))}</button>`:'Hidden card'}</p>`;}).join(''):'<p class="muted">Select cards, then choose a destination. Selection order is preserved.</p>';$('#journal').innerHTML=match.log.map(l=>`<p>${esc(l)}</p>`).join('');$('#undo').disabled=!history.length;$('#redo').disabled=!future.length;design?.matchUpdated();resolutionUI?.render();}
$('#dest-zone').innerHTML=zones.map(z=>`<option value="${z}">${zoneName(z)}</option>`).join('');$('#dest-zone').value='waiting';$('#control-player').onchange=()=>{selected=[];renderMatch();};$('#show-hidden').onchange=renderMatch;$('#clear-selection').onclick=()=>{selected=[];renderMatch();};$('#advance').onclick=advancePhase;$('#phase-override').onchange=e=>commit('Phase override',()=>match.phase=+e.target.value);$('#attack-step').onchange=e=>commit('Attack step: '+e.target.value,()=>match.step=e.target.value);
function openPile(p,z){pile={p,z,search:'',peek:false};renderPile();}
function renderPile(){if(!pile)return;const {p,z,search,peek}=pile,a=match.players[p].zones[z],hidden=z==='deck'||z==='stock'||(z==='hand'&&p!==cp()&&!$('#show-hidden').checked);showDialog(`<h2>Player ${p+1} · ${esc(zoneName(z))}</h2><p class="muted">${a.length} cards · displayed bottom / first → top / last. Click in the order you want to move cards.</p><div class="pile-tools"><input id="pile-search" aria-label="Search this pile" value="${esc(search)}" placeholder="Search names, numbers and abilities"><div class="toolbar">${hidden?`<button id="pile-peek">${peek?'Stop inspecting':'Privately inspect / search'}</button>`:''}<button id="pile-select-all">Select visible cards</button><button id="pile-clear">Clear</button><button id="pile-top">Move selection to top</button><button id="pile-bottom">Move selection to bottom</button><button id="pile-reverse">Reverse selected order</button><button id="pile-done" class="primary">Done · ${selected.length} selected</button></div><p class="muted">Use the table controls to move selected cards to another zone, reveal them, or change orientation.</p></div><div class="pile-grid">${a.map((c,i)=>({c,i})).filter(({c})=>{const info=catalog.get(c.id);return !search||((!hidden||peek)&&[info?.name,info?.code,...info?.ability||[]].join(' ').toLowerCase().includes(search.toLowerCase()));}).map(({c,i})=>`<div class="pile-card ${isSelected(p,z,c)?'selected':''}" data-ref="${p}|${z}|${c.uid}"><button class="art-button" data-select="${p}|${z}|${c.uid}">${(!hidden&&!c.faceDown||peek&&['deck','stock','hand'].includes(z))||c.revealed?img(catalog.get(c.id)):'<span class="card-back">W</span>'}</button><small>#${i+1} ${i===0?'· bottom':''}${i===a.length-1?'· top':''}</small>${(!hidden&&!c.faceDown||peek&&['deck','stock','hand'].includes(z))||c.revealed?`<button class="link" data-inspect="${esc(c.id)}">Read card</button>`:''}<small>${selected.findIndex(r=>r.uid===c.uid)>=0?'Selection '+(selected.findIndex(r=>r.uid===c.uid)+1):''}</small></div>`).join('')}</div>`);$('#pile-search').oninput=e=>{pile.search=e.target.value;const pos=e.target.selectionStart;renderPile();$('#pile-search').focus();$('#pile-search').setSelectionRange(pos,pos);};if($('#pile-peek'))$('#pile-peek').onclick=()=>{pile.peek=!pile.peek;renderPile();};$('#pile-select-all').onclick=()=>{for(const c of a){const info=catalog.get(c.id);if((!search||(!hidden||peek)&&[info?.name,info?.code,...info?.ability||[]].join(' ').toLowerCase().includes(search.toLowerCase()))&&!isSelected(p,z,c))selected.push(ref(p,z,c));}renderMatch();renderPile();};$('#pile-clear').onclick=()=>{selected=[];renderMatch();renderPile();};$('#pile-reverse').onclick=()=>{selected.reverse();renderPile();};$('#pile-top').onclick=()=>commit('Reordered '+zoneName(z),()=>move(match,selected.filter(r=>r.p===p&&r.z===z),p,z,'top'));$('#pile-bottom').onclick=()=>commit('Reordered '+zoneName(z),()=>move(match,selected.filter(r=>r.p===p&&r.z===z),p,z,'bottom'));$('#pile-done').onclick=()=>{$('#dialog').close();pile=null;renderMatch();};}
const actions={
 stand:()=>{for(const [z,a] of Object.entries(match.players[cp()].zones))if(stage(z))a.forEach(c=>c.orientation='stand');},
 draw:()=>{if(resolver.auto(match).enabled)return resolver.drawCards(match,cp(),amount());const n=draw(match,cp(),amount());if(n<amount())toast(`Drew ${n}. Deck empty: refresh, then draw the remaining ${amount()-n}.`);},
 clock:()=>{if(resolver.auto(match).enabled&&resolver.auto(match).clockedTurn===match.turn)throw Error('The optional clock action was already used this turn. Use an explicit manual zone move for a card effect.');const r=selected.filter(r=>r.p===cp()&&r.z==='hand');if(r.length!==1)throw Error('Select exactly one card from this player’s hand.');move(match,r,cp(),'clock');if(resolver.auto(match).enabled)resolver.auto(match).clockedTurn=match.turn;if(resolver.auto(match).enabled)resolver.drawCards(match,cp(),2);else draw(match,cp(),2);selected=[];},
 mulligan:()=>{const p=cp();if(match.players[p].mulligan)throw Error('This player has already mulliganed. Use manual moves for an override.');const r=selected.filter(r=>r.p===p&&r.z==='hand');move(match,r,p,'waiting');if(resolver.auto(match).enabled)resolver.drawCards(match,p,r.length);else draw(match,p,r.length);match.players[p].mulligan=true;selected=[];},
 shuffle:()=>shuffle(match.players[cp()].zones.deck),refresh:()=>refresh(match,cp()),
 level:()=>{const r=selected.filter(r=>r.p===cp()&&r.z==='clock');if(r.length!==1)throw Error('Inspect clock and select one of its bottom seven cards.');levelUp(match,cp(),r[0].uid);selected=[];},
 pay:()=>{const z=match.players[cp()].zones;if(z.stock.length<amount())throw Error('Not enough stock. Use manual movement for a special cost.');for(let i=0;i<amount();i++){const c=z.stock.pop();c.faceDown=false;z.waiting.push(c);}},
 trigger:()=>{if(!match.players[cp()].zones.deck.length)throw Error('Refresh the empty deck first.');draw(match,cp(),1,'resolution');match.step='Trigger';},
 stock:()=>{const z=match.players[cp()].zones,r=selected.filter(r=>r.p===cp()&&r.z==='resolution');if(r.length)move(match,r,cp(),'stock');else if(z.resolution.length)z.stock.push(z.resolution.pop());else throw Error('No trigger card in resolution.');selected=[];},
 damage:()=>resolver.auto(match).enabled?resolver.damage(match,cp(),amount(),selected[0]?.uid):startDamage(match,cp(),amount()),'damage-reveal':()=>damageReveal(match,cp(),catalog),'damage-finish':()=>finishDamage(match,cp()),
 encore:()=>{const z=match.players[cp()].zones;for(const key of Object.keys(z))if(stage(key)){const reverse=z[key].filter(c=>c.orientation==='reverse');move(match,reverse.map(c=>ref(cp(),key,c)),cp(),'waiting');}z.waiting.push(...z.climax.splice(0));toast('Reversed cards and climax moved. Resolve encore manually; discard to seven cards if needed.');},
 attack:()=>{if(resolver.auto(match).enabled){if(selected.length!==1)throw Error('Select one attacker.');return resolver.beginAttack(match,selected[0],$('#attack-type').value.toLowerCase());}const r=selected.filter(r=>r.p===cp()&&r.z.startsWith('center-'));if(r.length!==1)throw Error('Select one center-stage attacker.');const c=match.players[r[0].p].zones[r[0].z].find(c=>c.uid===r[0].uid);c.orientation='rest';match.step='Attack declaration';match.log.unshift($('#attack-type').value+' attack declared by Player '+(cp()+1));},
 move:()=>{if(!selected.length)throw Error('Select cards first.');const moved=move(match,selected,+$('#dest-player').value,$('#dest-zone').value,$('#placement').value);if(!moved.length)throw Error('No cards moved.');selected=[];},
 rest:()=>orientation('rest'),reverse:()=>orientation('reverse'),'stand-selected':()=>orientation('stand'),
 flip:()=>modify(c=>c.faceDown=!c.faceDown),reveal:()=>modify(c=>c.revealed=!c.revealed),note:()=>{const t=prompt('Card note, such as “Power 8500 · Soul 2”');if(t!==null)modify(c=>c.note=t.slice(0,100));}
};
function modify(fn){if(!selected.length)throw Error('Select one or more cards first.');for(const r of selected){const c=match.players[r.p].zones[r.z].find(c=>c.uid===r.uid);if(c)fn(c);}}
function orientation(o){modify(c=>c.orientation=o);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-add],[data-inspect],[data-decrement],[data-remove],[data-load],[data-delete],[data-duplicate],[data-action],[data-pile],[data-select],[data-stage]');if(!b)return;const d=b.dataset;if(d.add)add(d.add);else if(d.inspect)inspect(d.inspect);else if(d.decrement){if(--draft.cards[d.decrement]<=0)delete draft.cards[d.decrement];saveDraft();renderDeck();}else if(d.remove){delete draft.cards[d.remove];saveDraft();renderDeck();}else if(d.load!==undefined){draft=structuredClone(saved[+d.load]);saveDraft();renderDeck();toast('Deck loaded.');}else if(d.duplicate!==undefined){duplicateDeck(saved[+d.duplicate]);}else if(d.delete!==undefined){if(confirm('Delete this saved deck?')){saved.splice(+d.delete,1);persist('ws-decks',saved);renderDeck();}}else if(d.action){const name=d.action;commit(`Player ${cp()+1}: ${b.textContent.trim()}`,()=>actions[name]());}else if(d.pile){const [p,z]=d.pile.split('|');if(design&&b.closest('#table'))design.clickPile(+p,z,b);else openPile(+p,z);}else if(d.select){const [p,z,uid]=d.select.split('|');if(design)design.clickCard({p:+p,z,uid},b,e);else toggle(+p,z,uid);}else if(d.stage){const [p,z]=d.stage.split('|'),c=match.players[+p].zones[z].at(-1);if(c&&design)design.clickCard({p:+p,z,uid:c.uid},b,e);else if(c)toggle(+p,z,c.uid);else if(design)design.emptyStage(+p,z,b);else if(selected.length){$('#dest-player').value=p;$('#dest-zone').value=z;toast('Destination selected. Press Move selected.');}}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"]')){e.preventDefault();e.target.click();}});
const checklist=[['Setup','Choose decks, randomize first player, shuffle, draw five each; select unwanted hand cards and mulligan once per player.'],['Stand & draw','Stand the active player’s characters; draw one. Check deck-empty and clock-seven conditions whenever they arise.'],['Clock','Optionally select one hand card, clock it and draw two. Choose level-up cards when required.'],['Main','Play characters to the five stage positions, replace or swap positions using manual moves, play events, use abilities, pay stock, discard, rest cards and manage markers.'],['Search & reveal','Inspect a pile, privately search, select cards in the desired order, reveal publicly or move to a destination. Shuffle after searches when instructed.'],['Climax','Move a climax from hand to the climax area and manually apply its effects.'],['Attacks','Select an attacker and declare frontal, side or direct attack. First player may attack only once on their first turn.'],['Triggers & counters','Reveal trigger to resolution, apply its icon effect manually, then move it to stock. Switch control to the defender to play counters and pay their costs.'],['Damage & cancellation','Control the damaged player. Start damage, reveal one card at a time until done or a climax cancels; resolve those revealed cards to clock or waiting room. Refresh during resolution if needed.'],['Battle & encore','Compare power manually, reverse defeated characters. Resolve encore costs and return characters rested when applicable. End / encore cleanup moves reversed characters and climax to waiting room.'],['Level-up','Inspect clock: bottom is #1. Choose one of the bottom seven, level it, and move the other six to waiting room. Repeat if needed. Four level cards meets a loss condition.'],['Refresh','With deck empty, use Refresh to shuffle waiting room into deck and immediately put the new top card into clock. Resolve pending level-up and resume the interrupted action.'],['Costs & overrides','Pay complete multi-part costs with manual moves before resolving refresh or level-up. Decks and stock are hidden, ordered piles. You may inspect them privately. Face-down memory/markers remain hidden until revealed.'],['End & next turn','Resolve end effects, clear temporary notes, discard hand to seven where required, then advance to the next player’s Stand phase.'],['Correct mistakes','Undo/redo table actions. Multi-select, reverse selection order and move to top/bottom to set exact pile order. Manual overrides remain available throughout.']];
$('#game-checklist').onclick=()=>{pile=null;showDialog('<p class="eyebrow">A FULL GAME, AT YOUR PACE</p><h2>Manual practice checklist</h2><p class="muted">The controls move cards; you decide when rules and effects apply.</p><ol class="checklist">'+checklist.map(([title,body])=>`<li><label><input type="checkbox"><b>${title}</b></label>${esc(body)}</li>`).join('')+'</ol>');};
function sources(){pile=null;showDialog(`<p class="eyebrow">AN HONEST LOOK AT THE COLLECTION</p><h2>Sources & catalog coverage</h2><p class="notice">This is an available-source catalog, not a verified complete catalog of all publicly released cards. Cards, promotions, artwork and restrictions still require reconciliation.</p><p>Imported: <b>${Number(coverage.english||0).toLocaleString()} English</b> and <b>${Number(coverage.japanese||0).toLocaleString()} Japanese</b> records. Updated ${esc(coverage.updated?.slice(0,10)||'—')}.</p><ul class="source-list">${(coverage.notes||[]).map(n=>`<li>${esc(n)}</li>`).join('')}</ul><p>${coverage.failures?.length||0} recorded source download failures.</p><p>Artwork links come from source card records. Failed artwork is labeled unavailable; it is never replaced with invented art. English and Japanese remain separate card identities. Blau and Rose are excluded.</p><ul class="source-list"><li><a href="https://ws-tcg.com/cardlist/" target="_blank" rel="noopener">Official Japanese card list</a></li><li><a href="https://en.ws-tcg.com/cardlist/" target="_blank" rel="noopener">Official English card list</a></li><li><a href="https://github.com/CCondeluci/WeissSchwarz-ENG-DB" target="_blank" rel="noopener">English mirror and record schema</a></li><li><a href="https://www.heartofthecards.com/code/cardlist.html" target="_blank" rel="noopener">Heart of the Cards · unofficial translation references</a></li><li><a href="https://en.ws-tcg.com/rules/" target="_blank" rel="noopener">Official English rules, quick manual and playmat</a></li><li><a href="https://en.ws-tcg.com/rules/deck/" target="_blank" rel="noopener">English construction and restriction list</a></li><li><a href="https://ws-tcg.com/rules/deck_rule/" target="_blank" rel="noopener">Japanese construction and restrictions</a></li></ul><p>Basic validation: 50 cards, at most eight climax, same-name copy counts, language, and recognized English copy-limit text. The EN restriction snapshot is ${restrictions?esc(restrictions.date):'not loaded'}. The Japanese snapshot includes 39 Neo Standard groups and Standard/Side bans. Conditional exceptions, all title exceptions, and all special deck text are not fully encoded. Check the official lists before tournament play.</p><p>Decks and practice state are saved in this browser. Export decks for backups or to transfer them to another device. No account synchronization is provided.</p>`);}
$('#about').onclick=sources;$('#footer-sources').onclick=sources;

function advancePhase(){if(match&&resolver.auto(match).enabled)return commit('Guided phase progression',()=>resolver.advance(match));if(match&&(resolver.auto(match).choice||resolver.auto(match).attack||resolver.auto(match).queue.length))return toast('Resolve the current choice before advancing.');commit('Advanced phase',()=>{const before=match.turn;nextPhase(match);if(match.turn!==before){match.attacksThisTurn=0;match.attackType=null;$('#control-player').value=String(match.active);}});}
function previousPhase(){commit('Phase correction: previous phase',()=>{if(match.phase>0)match.phase--;else if(match.turn>1){match.turn--;match.active=1-match.active;match.phase=6;}else throw Error('Already at the first phase of the game.');});}
function instanceAt(r){return match?.players[r.p].zones[r.z]?.find(c=>c.uid===r.uid);}
function selectCards(refs,player){selected=refs;if(player!==undefined){$('#control-player').value=String(player);$('#dest-player').value=String(player);}renderMatch();if(pile)renderPile();}
function performMove(refs,p,to,position='top',orientation){commit('Manual movement to '+zoneName(to),()=>{const moved=move(match,refs,p,to,position);if(orientation)moved.forEach(c=>c.orientation=orientation);selected=[];});}
design=mountAtelier({state:()=>({cards,catalog,match,selected,player:cp(),pile}),view,toast,card:id=>catalog.get(id),name:id=>catalog.has(id)?displayName(catalog.get(id)):'Card unavailable',englishAbility:id=>presentation?.get(id)?.ability?.join(' ')||'',instance:instanceAt,readable:r=>{const c=instanceAt(r);return !!c&&(visible(r.p,r.z,c)||pile?.peek&&pile.p===r.p&&pile.z===r.z&&(!c.faceDown||['deck','stock','hand'].includes(r.z)));},image:id=>img(catalog.get(id)),details:readableDetails,inspect,zoneName,openPile,select:selectCards,setPlayer:p=>{$('#control-player').value=String(p);renderMatch();},setAmount:n=>$('#amount').value=String(n),action:name=>commit('Player '+(cp()+1)+': '+name,()=>actions[name]()),move:performMove,advancePhase,previousPhase,setStep:step=>commit('Attack step: '+step,()=>match.step=step),swapStage:(r,to)=>commit('Stage position swap',()=>{const z=match.players[r.p].zones;[z[r.z],z[to]]=[z[to],z[r.z]];[z['markers:'+r.z],z['markers:'+to]]=[z['markers:'+to],z['markers:'+r.z]];selected=[];}),placeStage:(r,to,rested)=>commit('Place character on '+zoneName(to),()=>{const z=match.players[r.p].zones;const old=z[to].map(c=>({p:r.p,z:to,uid:c.uid}));if(old.length)move(match,old,r.p,'waiting');if(z['markers:'+to].length)z.waiting.push(...z['markers:'+to].splice(0));move(match,[r],r.p,to);if(rested)z[to].at(-1).orientation='rest';selected=[];}),declareAttack:(r,type,override=false)=>commit((override?'Manual override: ':'')+type+' attack',()=>{if(!override&&resolver.auto(match).enabled)return resolver.beginAttack(match,r,type);if(resolver.auto(match).choice||resolver.auto(match).attack)throw Error('Finish or abort the pending guided sequence first.');const c=instanceAt(r);if(!c)throw Error('Choose a stage character.');c.orientation='rest';match.attackType=type[0].toUpperCase()+type.slice(1);match.attacksThisTurn=(match.attacksThisTurn||0)+1;match.step='Attack declaration';})});
resolutionUI=mountResolution({state:()=>match,resolver,commit,dialog:showDialog,inspect,image:id=>img(catalog.get(id)),name:id=>displayName(catalog.get(id))});
$('#browse-builder-cards').onclick=()=>{$('#search').focus();$('#search').scrollIntoView?.({block:'center',behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});};

async function init(){try{const [sample,names,references,starters,cov]=await Promise.all(['cards','series-names','translation-references','starter-decks','coverage'].map(f=>fetch('data/'+f+'.json').then(r=>{if(!r.ok)throw Error('Could not load '+f);return r.json();})));seriesNames=names;translationReferences=references.references;includedDecks=starters.decks;cards=[...new Map([...sample,...starters.cards].map(c=>[c.id,c])).values()];catalog=new Map(cards.map(c=>[c.id,c]));coverage=cov;installIncludedDecks(includedDecks);rebuildPresentation();try{[restrictions,jpRestrictions]=await Promise.all(['restrictions','jp-restrictions'].map(f=>fetch('data/'+f+'.json').then(r=>r.ok?r.json():null)));}catch{}$('#catalog-count').textContent=cards.length.toLocaleString();seriesOptions();filter();renderDock();renderSetup();if(activeView==='decks')renderDeck();if(match){$('#match-setup').hidden=true;renderMatch();}const index=await fetch('data/index.json').then(r=>r.json()),all=[];let next=0;async function load(){while(next<index.chunks.length){const f=index.chunks[next++],r=await fetch('data/'+f);if(!r.ok)throw Error('A catalog section could not load. Reload to retry.');all.push(...await r.json());}}await Promise.all([load(),load(),load()]);cards=all;catalog=new Map(cards.map(c=>[c.id,c]));rebuildPresentation();$('#catalog-count').textContent=cards.length.toLocaleString();seriesOptions();filter();renderDock();if(activeView==='decks')renderDeck();renderSetup();if(match)renderMatch();}catch(e){$('#results').textContent=e.message;toast(e.message);}}init();
